function sameLogin(one, other) {
    if (one == null || other == null)
        return false;
    return one.trim().toLowerCase() === other.trim().toLowerCase();
}
export function canEditPullRequestChangeRequest(detail) {
    if (detail.capabilities.edit?.changeRequest !== true)
        return false;
    if (detail.viewerPermissions.editChangeRequest !== undefined) {
        return detail.viewerPermissions.editChangeRequest;
    }
    return (sameLogin(detail.viewer, detail.author?.login) ||
        detail.viewerPermissions.actions.includes("merge"));
}
/** Hosts do not support rewriting review summaries through comment mutations. */
export function canEditPullRequestComment(detail, comment) {
    if (detail.capabilities.edit?.comment !== true)
        return false;
    if (comment.kind !== "issue-comment" && comment.kind !== "review-comment")
        return false;
    if (comment.canEdit !== undefined)
        return comment.canEdit;
    return sameLogin(detail.viewer, comment.author?.login);
}
export function canResolvePullRequestThread(detail, thread) {
    return detail.viewerPermissions.resolve && thread.canResolve !== false;
}
